<script setup lang="ts">
import {computed,ref} from 'vue';
import {NButton,NCollapse,NCollapseItem,NEmpty,NModal,NSelect,NTag,useDialog} from 'naive-ui';
import {Plus,Pencil,Trash2,LockKeyhole} from '@lucide/vue';
import type {Chapter,Entity,Novel,Preview,Scope} from '../studio-api';
import EntityEditor from './EntityEditor.vue';
const props=defineProps<{novel:Novel;chapters?:Chapter[];chapterId?:string;preview:Preview|null;editable:boolean;busy:boolean;save:(payload:Record<string,unknown>)=>Promise<unknown>}>();
const scope=ref<Scope>('world'),entity=ref<Entity|null>(null),target=ref(''),invalid=ref(false),saving=ref(false);
const dialog=useDialog();
const names:Record<Scope,string>={world:'世界观',characters:'角色',creation:'创作',chapters:'章设定'};
const options=Object.entries(names).map(([value,label])=>({value,label}));
const entities=computed(()=>scope.value==='characters'?props.novel.characters.map(e=>props.preview?.characters[e.id]??e):scope.value==='chapters'?(props.chapters??props.novel.chapters).map(c=>c.entity):props.novel[scope.value]);
function edit(value?:Entity){target.value=value?.id??'';entity.value=value?JSON.parse(JSON.stringify(value)):{...JSON.parse(JSON.stringify(props.novel.template_fields[scope.value])),id:'',name:'',type:scope.value==='characters'?'human':scope.value==='world'?'world':'creation'}}
async function save(){if(!entity.value)return;saving.value=true;try{const {id,...value}=entity.value;const result=await props.save({scope:scope.value,target:target.value,entity:value});if(result)entity.value=null}finally{saving.value=false}}
function remove(value:Entity){dialog.warning({title:`删除“${value.name}”？`,content:'这项资料将从本书中删除，原字段模板不受影响。',positiveText:'删除',negativeText:'取消',onPositiveClick:()=>props.save({scope:scope.value,target:value.id,delete:true})})}
defineExpose({showCharacters:()=>{scope.value='characters'},newCharacter:()=>{scope.value='characters';edit()}});
</script>
<template><section class="fields-panel"><header class="panel-heading"><div><span class="eyebrow">小说资料</span><h2>{{names[scope]}}</h2></div><NButton v-if="editable&&['world','characters','creation'].includes(scope)" secondary type="primary" :disabled="busy" @click="edit()"><template #icon><Plus :size="16"/></template>新增{{scope==='characters'?'角色':'资料'}}</NButton></header><NSelect v-model:value="scope" :options="options" aria-label="资料类别" class="scope-select"/><p class="panel-caption">{{novel.created?(scope==='characters'?'角色状态对应当前选中幕。新建角色不会自动加入群聊。':'资料独立保存在本书中，重置演绎不会删除设定。'):'这里只整理本书的构思资料。可以先记录已知内容，再通过对话逐步补充。'}}</p><NEmpty v-if="!entities.length" :description="`还没有${names[scope]}资料`"><template #extra><NButton v-if="editable&&['world','characters','creation'].includes(scope)" @click="edit()">添加第一项</NButton><span v-else>也可以在对话中让 AI 逐步补充。</span></template></NEmpty>
 <NCollapse class="entity-cards"><NCollapseItem v-for="e in entities" :key="e.id" :name="e.id" :title="e.name"><template #header-extra><NTag size="small" :bordered="false">{{e.type}}</NTag></template><div class="entity-details"><div v-for="d in e.description" :key="d.name" class="entity-value"><div><strong>{{d.name}}</strong><span v-if="d.visibility!==2" class="privacy-note"><LockKeyhole :size="11"/>{{d.visibility===0?'仅 GM':'仅自己'}}</span></div><p>{{d.value.join('\n')||'待补充'}}</p></div><div v-for="a in e.special_attributes" :key="a.key" class="entity-value"><div><strong>{{a.key}}</strong><span class="attribute-value">{{Array.isArray(a.current_value)?a.current_value.join('、'):String(a.current_value)}}</span></div><p v-if="a.how">{{a.how}}</p><small v-if="a.when">修改时机：{{a.when}}</small></div><p v-if="!e.description.length&&!e.special_attributes.length" class="muted">暂无字段。</p><div class="entity-actions"><NButton secondary :disabled="busy||!editable||(scope==='chapters'&&e.id!==chapterId)" @click="edit(e)"><template #icon><Pencil :size="14"/></template>编辑</NButton><NButton v-if="['world','creation'].includes(scope)" quaternary type="error" :disabled="busy||!editable" @click="remove(e)"><template #icon><Trash2 :size="14"/></template>删除</NButton></div></div></NCollapseItem></NCollapse>
 <NModal :show="!!entity" @update:show="!$event&&(entity=null)" preset="card" :title="`${target?'编辑':'新增'}${names[scope]}`" class="entity-modal" :style="{width:'min(680px, calc(100vw - 24px))'}" :mask-closable="!saving"><div class="entity-modal-body"><EntityEditor v-if="entity" :key="target+scope" :value="entity" :disabled="saving" @invalid="invalid=$event"/></div><template #footer><div class="modal-actions"><NButton :disabled="saving" @click="entity=null">取消</NButton><NButton type="primary" :loading="saving" :disabled="invalid" @click="save">保存资料</NButton></div></template></NModal>
</section></template>
